function note(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<void> {
  return record(orgId, action, input).then(() => undefined);
}

/** Comments carry only an issue id; the feed's project filter needs the project. */
async function projectOfIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<ProjectId | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

