type ActivityQuery = Omit<ActivityFilterInput, "limit" | "cursor">;

/**
 * Both ends of a time range are inclusive. A range that finishes before it
 * starts is refused rather than silently matching nothing.
 */
function activityFilters(input: ActivityQuery): readonly SQL[] {
  const since =
    input.since === undefined ? undefined : toIsoTimestamp(input.since);
  const until =
    input.until === undefined ? undefined : toIsoTimestamp(input.until);

  if (since !== undefined && until !== undefined && until < since) {
    throw new Error("A time range must not end before it starts");
  }

  return compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
